// DOM-safe HTML insertion using a Range fragment (no live innerHTML sink).
function setHTMLSafe(el, html) {
    const s = String(html == null ? '' : html);
    const range = document.createRange();
    range.setStart(el, 0);
    range.setEnd(el, 0);
    const frag = range.createContextualFragment(s);
    el.replaceChildren.apply(el, Array.from(frag.childNodes));
}

