// T011 — searchAllEnvironments: client-side fan-out over the same view-model data
// used by buildNavigatorTree, returning grouped SearchResult objects for the vCenter
// global search dropdown (TopNavBar). No new backend endpoint is required for v1.
function searchAllEnvironments(query, tree) {
    if (!query?.trim() || !tree?.length) return [];
    const q = query.toLowerCase().trim();
    const hits = [];
    function walk(nodes, groupLabel) {
        for (const n of nodes || []) {
            const label = (n.label || '').toLowerCase();
            if (label.includes(q)) hits.push({ type: n.type, id: n.id, label: n.label, sublabel: groupLabel, navigatorNodeId: n.id });
            if (n.children?.length) walk(n.children, n.label);
        }
    }
    walk(tree, 'Datacenter');
    const grouped = {};
    for (const h of hits) { (grouped[h.type] = grouped[h.type] || []).push(h); }
    return Object.keys(grouped).map((type) => ({ type, items: grouped[type] }));
}
