    // 917-drag-and-drop-reordering-for-firewall-rules: reorder rules via HTML5 drag-and-drop.
    const handleRuleDragStart = (e, idx) => {
        e.dataTransfer.setData('text/plain', String(idx));
        e.dataTransfer.effectAllowed = 'move';
    };
    const handleRuleDragOver = (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
    };
    const handleRuleDrop = (e, targetIdx) => {
        e.preventDefault();
        const sourceIdx = parseInt(e.dataTransfer.getData('text/plain'), 10);
        if (Number.isNaN(sourceIdx) || sourceIdx === targetIdx) return;
        const reordered = [...firewallRules];
        const [moved] = reordered.splice(sourceIdx, 1);
        reordered.splice(targetIdx, 0, moved);
        setFirewallRules(reordered.map((rule, i) => ({ ...rule, pos: i + 1 })));
    };

