// useNodeKeyboardShortcuts: attach number-key shortcuts for switching Node Detail tabs.
function useNodeKeyboardShortcuts(tabs, activeTab, setActiveTab) {
    useEffect(() => {
        const handler = (e) => {
            if (!e.key || e.ctrlKey || e.metaKey || e.altKey) return;
            const idx = parseInt(e.key, 10);
            if (isNaN(idx) || idx < 1 || idx > (tabs || []).length) return;
            const tab = tabs[idx - 1];
            if (tab && tab !== activeTab) {
                e.preventDefault();
                setActiveTab(tab);
            }
        };
        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [tabs, activeTab, setActiveTab]);
}

