// Memory input with MB/GB unit selector - makes it easier to set RAM values
// (memory-swap-validation): values are clamped to [minMB, maxMB] and NaN/negative
// input is rejected instead of silently coercing to 0, so a bad keystroke can't
// stage an out-of-range memory/swap value for save.
const MemoryInputField = ({ label, value, onChange, disabled = false, needsRestart = false, minMB = 128, stepMB = 128, maxMB = 4194304, t }) => {
    const { isCorporate } = useLayout();
    // value is always in MB internally
    const [unit, setUnit] = useState(value >= 1024 ? 'GB' : 'MB');
    const [error, setError] = useState('');

    const displayValue = unit === 'GB' ? (value / 1024) : value;
    const step = unit === 'GB' ? 0.5 : stepMB;
    const min = unit === 'GB' ? (minMB / 1024) : minMB;
    const max = unit === 'GB' ? (maxMB / 1024) : maxMB;

    const handleValueChange = (rawValue) => {
        const parsed = parseFloat(rawValue);
        if (rawValue === '' || isNaN(parsed)) {
            // Don't stage a change on an incomplete/invalid keystroke; keep the
            // last valid value until the field has something parseable.
            setError(t ? t('invalidMemoryValue') : 'Enter a valid number');
            return;
        }
        // Convert back to MB for storage
        const mbValue = Math.round(unit === 'GB' ? parsed * 1024 : parsed);
        const clamped = Math.min(Math.max(mbValue, minMB), maxMB);
        if (clamped !== mbValue) {
            setError(t ? t('memoryValueClamped', { params: { min: minMB, max: maxMB } }) : `Clamped to range ${minMB}-${maxMB} MB`);
        } else {
            setError('');
        }
        onChange(clamped);
    };

    const handleUnitChange = (newUnit) => {
        setUnit(newUnit);
        // Value stays the same in MB, just display changes
    };

    return (
        <div>
            <label className={isCorporate ? 'corp-label' : 'block text-xs font-medium text-gray-400 mb-1'}>
                {label}
                {needsRestart && <span className="ml-2 text-[10px] px-1.5 py-0.5 bg-red-500/20 text-red-400 rounded font-medium">{t ? t('needsRestart') : 'NEEDS RESTART'}</span>}
            </label>
            <div className="flex gap-2">
                <input
                    type="number"
                    value={displayValue}
                    onChange={e => handleValueChange(e.target.value)}
                    min={min}
                    max={max}
                    step={step}
                    disabled={disabled}
                    className={isCorporate ? 'corp-input flex-1' : `flex-1 px-3 py-2 bg-proxmox-dark border ${error ? 'border-red-500/60' : 'border-proxmox-border'} rounded-lg text-white text-sm focus:outline-none focus:border-proxmox-orange disabled:opacity-50`}
                />
                <select
                    value={unit}
                    onChange={e => handleUnitChange(e.target.value)}
                    disabled={disabled}
                    // (memory-swap-unit-select-width): `corp-input` sets width:100%, which - as a
                    // flex sibling of the flex-1 amount input - made the unit select's flex-basis
                    // resolve to the full row width, starving the amount input down to ~18px.
                    // `w-20 shrink-0` (loaded after corp-input in the cascade) pins it back to a
                    // fixed width so the amount input can actually grow into the remaining space.
                    className={isCorporate ? 'corp-input w-20 shrink-0' : 'w-20 px-2 py-2 bg-proxmox-dark border border-proxmox-border rounded-lg text-white text-sm focus:outline-none focus:border-proxmox-orange'}
                >
                    <option value="MB">MB</option>
                    <option value="GB">GB</option>
                </select>
            </div>
            {error ? (
                <p className="text-xs text-red-400 mt-1">{error}</p>
            ) : (
                <p className={isCorporate ? 'corp-help-text' : 'text-xs text-gray-500 mt-1'}>
                    {unit === 'MB' ? `${(value / 1024).toFixed(1)} GB` : `${value} MB`}
                </p>
            )}
        </div>
    );
};

