                                                setTabOrder(prev => {
                                                    const next = [...prev];
                                                    const from = next.indexOf(draggedTab);
                                                    const to = next.indexOf(item.id);
                                                    if (from < 0 || to < 0) return prev;
                                                    next.splice(from, 1);
                                                    next.splice(to, 0, draggedTab);
                                                    return next;
                                                });
                                                setDraggedTab(null);
