// useVmKeyboardShortcuts: enable number-key shortcuts for the VM table tabs.
function useVmKeyboardShortcuts(tabs = [], setActiveTab) {
    useEffect(() => {
        if (!setActiveTab) return;
        const onKey = (e) => {
            if (!/^[0-9]$/.test(e.key) || e.target?.tagName === 'INPUT' || e.target?.tagName === 'TEXTAREA') return;
            const idx = parseInt(e.key, 10) - 1;
            if (idx >= 0 && idx < (tabs || []).length) {
                e.preventDefault();
                setActiveTab(tabs[idx]);
            }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [tabs, setActiveTab]);
}

