// VmTableResizablePanels: two-column resizable layout for the VM table.
function VmTableResizablePanels({ left, right, initialLeft = 320, minLeft = 200, maxLeft = 600 }) {
    const [leftWidth, setLeftWidth] = useState(() => {
        try { return parseInt(localStorage.getItem('proxmoxvex_vm_table_left') || initialLeft, 10); }
        catch { return initialLeft; }
    });
    const [dragging, setDragging] = useState(false);
    const containerRef = useRef(null);

    useEffect(() => {
        if (!dragging) return;
        const onMove = (e) => {
            if (!containerRef.current) return;
            const rect = containerRef.current.getBoundingClientRect();
            const x = (e.clientX || e.touches?.[0]?.clientX || 0) - rect.left;
            const w = Math.max(minLeft, Math.min(maxLeft, x));
            setLeftWidth(w);
        };
        const onUp = () => {
            setDragging(false);
            try { localStorage.setItem('proxmoxvex_vm_table_left', String(leftWidth)); } catch { }
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
        window.addEventListener('touchmove', onMove);
        window.addEventListener('touchend', onUp);
        return () => {
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
            window.removeEventListener('touchmove', onMove);
            window.removeEventListener('touchend', onUp);
        };
    }, [dragging, leftWidth, minLeft, maxLeft]);

    return (
        <div ref={containerRef} className="flex w-full h-full overflow-hidden">
            <div className="h-full overflow-auto" style={{ width: leftWidth }}>
                {left}
            </div>
            <div
                className="w-1 cursor-col-resize hover:bg-proxmox-blue/30"
                style={{ background: 'var(--corp-border-medium)' }}
                onMouseDown={() => setDragging(true)}
                onTouchStart={() => setDragging(true)}
                role="separator"
                aria-orientation="vertical"
            >
            </div>
            <div className="flex-1 h-full overflow-auto">
                {right}
            </div>
        </div>
    );
}

