// MigrationPlanUndoAction: shows a temporary undo button after a migration plan action.
function MigrationPlanUndoAction({ action, onUndo, timeout = 5000 }) {
    const [visible, setVisible] = React.useState(true);

    React.useEffect(() => {
        if (!timeout) return;
        const timer = setTimeout(() => setVisible(false), timeout);
        return () => clearTimeout(timer);
    }, [timeout]);

    const handleUndo = () => {
        setVisible(false);
        onUndo?.(action);
    };

    if (!visible || !action) return null;
    return (
        <div className="flex items-center gap-2 px-3 py-2 rounded border border-proxmox-border bg-proxmox-card" data-testid="migration-plan-undo-action">
            <span className="text-xs text-proxmox-textMuted">{action.label || 'Action'} applied</span>
            <button
                onClick={handleUndo}
                className="text-xs text-proxmox-blue hover:text-proxmox-blueLight underline"
            >
                Undo
            </button>
        </div>
    );
}

