// LxcTableDragHandle: drag handle for reordering LXC table rows.
function LxcTableDragHandle({ id, index, onReorder, children }) {
    const [dragOver, setDragOver] = useState(false);
    return (
        <div
            className={`cursor-grab active:cursor-grabbing p-1 rounded ${dragOver ? 'bg-proxmox-blue/20' : ''}`}
            draggable
            onDragStart={(e) => e.dataTransfer.setData('text/plain', String(index))}
            onDragOver={(e) => {
                e.preventDefault();
                setDragOver(true);
            }}
            onDragLeave={() => setDragOver(false)}
            onDrop={(e) => {
                e.preventDefault();
                setDragOver(false);
                const from = parseInt(e.dataTransfer.getData('text/plain'), 10);
                if (!Number.isNaN(from) && onReorder) {
                    onReorder(from, index);
                }
            }}
            title="Drag to reorder"
        >
            {children}
        </div>
    );
}

