// LxcTableKeyboardShortcuts: attach keyboard shortcuts for the LXC table.
function LxcTableKeyboardShortcuts({ shortcuts }) {
    useEffect(() => {
        const onKeyDown = (e) => {
            const key = e.key.toLowerCase();
            const combo = (e.ctrlKey ? 'ctrl+' : '') + (e.shiftKey ? 'shift+' : '') + key;
            const handler = shortcuts && shortcuts[combo];
            if (handler) {
                e.preventDefault();
                handler();
            }
        };
        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
    }, [shortcuts]);
    return null;
}

