// Replace raw Cluster ID / VMID input boxes inside plugin iframes with
// dropdowns populated from the main application. This is applied to every
// plugin page without needing to edit each plugin's HTML individually.
function _enhancePluginIframe(iframe) {
    try {
        const doc = iframe.contentDocument;
        if (!doc || !doc.body) return;
        const clusterInputs = doc.querySelectorAll('input[name="cluster_id"]');
        const vmInputs = doc.querySelectorAll('input[name="vmid"]');
        if (!clusterInputs.length && !vmInputs.length) return;

        const fetchClusters = async () => {
            const res = await fetch('/api/clusters', { credentials: 'same-origin', headers: { 'X-Requested-With': 'XMLHttpRequest' } });
            return res.ok ? await res.json() : [];
        };
        const fetchVms = async (clusterId) => {
            if (!clusterId) return [];
            const res = await fetch(`/api/clusters/${encodeURIComponent(clusterId)}/vms`, { credentials: 'same-origin', headers: { 'X-Requested-With': 'XMLHttpRequest' } });
            if (!res.ok) return [];
            const data = await res.json();
            return (data && data.vms) || [];
        };

        (async () => {
            const clusters = await fetchClusters();
            clusterInputs.forEach(input => {
                const current = input.value;
                const select = doc.createElement('select');
                select.name = 'cluster_id';
                if (input.required) select.required = true;
                select.className = input.className;
                select.style.cssText = input.style.cssText;
                function _esc(str) {
                    return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
                }
                select.innerHTML = '<option value="">Select a cluster</option>' +
                    clusters.map(c => `<option value="${_esc(c.id)}" ${c.id === current ? 'selected' : ''}>${_esc(c.display_name || c.name || c.id)}</option>`).join('');
                if (input.parentNode) input.parentNode.replaceChild(select, input);
            });

            for (const input of Array.from(vmInputs)) {
                const form = input.closest('form');
                const clusterSelect = (form ? form.querySelector('select[name="cluster_id"], input[name="cluster_id"]') : null)
                    || doc.querySelector('select[name="cluster_id"], input[name="cluster_id"]');
                const current = input.value;
                const select = doc.createElement('select');
                select.name = 'vmid';
                if (input.required) select.required = true;
                select.className = input.className;
                select.style.cssText = input.style.cssText;
                select.innerHTML = '<option value="">Select a VM</option>';
                if (input.parentNode) input.parentNode.replaceChild(select, input);

                const updateVms = async () => {
                    const c = clusterSelect ? (clusterSelect.tagName === 'SELECT' ? clusterSelect.value : clusterSelect.value) : '';
                    const vms = c ? await fetchVms(c) : [];
                    function _esc(str) {
                        return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
                    }
                    const opts = ['<option value="">Select a VM</option>'];
                    vms.forEach(v => {
                        const s = String(v.vmid) === current ? 'selected' : '';
                        opts.push(`<option value="${_esc(v.vmid)}" ${s}>${_esc(v.vmid)} — ${_esc(v.name || '')} (${_esc(v.node || '')})</option>`);
                    });
                    select.innerHTML = opts.join('');
                };
                if (clusterSelect) {
                    clusterSelect.addEventListener('change', () => { updateVms(); });
                }
                await updateVms();
            }
        })().catch(() => { });
    } catch (e) { }
}

// MetricChartColorTheme: dark-mode aware color theme wrapper for the Metric Chart page.
function MetricChartColorTheme({ children }) {
    const [theme, setTheme] = React.useState(() => document.documentElement?.getAttribute('data-theme') || 'proxmoxDark');

    React.useEffect(() => {
        const observer = new MutationObserver((mutations) => {
            mutations.forEach((m) => {
                if (m.attributeName === 'data-theme') {
                    setTheme(document.documentElement?.getAttribute('data-theme') || 'proxmoxDark');
                }
            });
        });
        observer.observe(document.documentElement, { attributes: true });
        return () => observer.disconnect();
    }, []);

    return (
        <div className={`metric-chart-theme ${theme}`} data-testid="metric-chart-color-theme" data-theme={theme}>
            {children}
        </div>
    );
}

