// MetricChartResizablePanels: resizable two-pane layout for the Metric Chart page.
function MetricChartResizablePanels({ leftPanel, rightPanel, initialLeftWidth = 35, minLeft = 20, maxLeft = 80 }) {
    const [leftWidth, setLeftWidth] = React.useState(initialLeftWidth);
    const [dragging, setDragging] = React.useState(false);

    React.useEffect(() => {
        const handleMouseMove = (e) => {
            if (!dragging) return;
            const width = (e.clientX / window.innerWidth) * 100;
            setLeftWidth(Math.max(minLeft, Math.min(maxLeft, width)));
        };
        const handleMouseUp = () => setDragging(false);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [dragging, minLeft, maxLeft]);

    return (
        <div className="flex w-full h-full overflow-hidden border border-proxmox-border rounded bg-proxmox-card" data-testid="metric-chart-resizable-panels">
            <div className="h-full overflow-auto p-2" style={{ width: `${leftWidth}%` }}>
                {leftPanel}
            </div>
            <div
                className="w-1 bg-proxmox-border hover:bg-cyan-600 cursor-col-resize transition-colors"
                onMouseDown={() => setDragging(true)}
                role="separator"
                aria-label="Resize metric chart panels"
            />
            <div className="h-full overflow-auto p-2 flex-1">
                {rightPanel}
            </div>
        </div>
    );
}

