function NodeMetricsBatchSelector({ nodes = [], selected = [], onChange, onRequest }) {
    const { t } = useTranslation();
    const toggle = (name) => {
        const next = selected.includes(name)
            ? selected.filter(n => n !== name)
            : [...selected, name];
        if (onChange) onChange(next);
    };
    return (
        <div className="p-3 border rounded border-proxmox-border bg-proxmox-dark">
            <div className="font-medium text-[13px] mb-2" style={{ color: '#e9ecef' }}>{t('nodes')}</div>
            <div className="flex flex-wrap gap-2 mb-3">
                {(nodes || []).map(n => (
                    <label key={n} className="flex items-center gap-1 text-[13px] cursor-pointer" style={{ color: 'var(--corp-text-secondary)' }}>
                        <input
                            type="checkbox"
                            checked={selected.includes(n)}
                            onChange={() => toggle(n)}
                            className="form-checkbox"
                        />
                        <span>{n}</span>
                    </label>
                ))}
            </div>
            <button
                onClick={() => onRequest && onRequest(selected)}
                className="px-3 py-1.5 text-[13px] rounded bg-proxmox-primary text-white hover:bg-proxmox-primary/90"
            >
                {t('apply')}
            </button>
        </div>
    );
}

