function PackerSyncPanel({ clusterId }) {
    const { t } = useTranslation();
    const [status, setStatus] = React.useState({ configured: false, last_sync: null, log: [] });
    const [loading, setLoading] = React.useState(false);
    const [templates, setTemplates] = React.useState([]);

    const testConnection = () => {
        setLoading(true);
        fetch(`/api/clusters/${clusterId}/packer/sync?test=1`)
            .then((r) => r.json())
            .then((data) => setStatus((s) => ({ ...s, configured: data.success, log: [...s.log, { level: 'info', message: data.message || t('testComplete') }] })))
            .catch((e) => setStatus((s) => ({ ...s, log: [...s.log, { level: 'error', message: e.message }] })))
            .finally(() => setLoading(false));
    };

    const runSync = () => {
        setLoading(true);
        fetch(`/api/clusters/${clusterId}/packer/sync`)
            .then((r) => r.json())
            .then((data) => {
                setTemplates(data.templates || []);
                setStatus({ configured: true, last_sync: data.synced_at, log: data.templates ? [{ level: 'info', message: `Synced ${data.templates.length} templates and ${data.images.length} images` }] : [] });
            })
            .catch((e) => setStatus((s) => ({ ...s, log: [...s.log, { level: 'error', message: e.message }] })))
            .finally(() => setLoading(false));
    };

    return (
        <div className="p-4 border rounded border-proxmox-border bg-proxmox-dark">
            <div className="font-medium text-[14px] mb-3" style={{ color: '#e9ecef' }}>{t('packerSync')}</div>
            <PackerSyncStatus configured={status.configured} lastSync={status.last_sync} />
            <div className="flex gap-2 mt-3">
                <button className="px-3 py-1 text-[12px] rounded bg-proxmox-primary text-white" onClick={testConnection} disabled={loading}>{t('testConnection')}</button>
                <button className="px-3 py-1 text-[12px] rounded bg-proxmox-primary text-white" onClick={runSync} disabled={loading}>{t('syncNow')}</button>
            </div>
            <PackerImportPanel clusterId={clusterId} templates={templates} setStatus={setStatus} loading={loading} setLoading={setLoading} />
            <div className="mt-3 space-y-1">
                {status.log.map((entry, i) => (
                    <div key={i} className="text-[12px]" style={{ color: entry.level === 'error' ? '#f87171' : 'var(--corp-text-secondary)' }}>{entry.message}</div>
                ))}
            </div>
        </div>
    );
}

