function PackerImportPanel({ clusterId, templates = [], setStatus, loading, setLoading }) {
    const { t } = useTranslation();
    const [selected, setSelected] = React.useState('');
    const [imported, setImported] = React.useState({ imported: false, newVmid: null });

    const doImport = () => {
        if (!selected) return;
        const item = templates.find((x) => String(x.vmid) === selected) || {};
        setLoading(true);
        fetch(`/api/clusters/${clusterId}/packer/import`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ source_vmid: item.vmid, type: item.type || 'qemu' })
        })
            .then((r) => r.json())
            .then((data) => {
                setImported({ imported: true, newVmid: data.new_vmid });
                setStatus((s) => ({ ...s, log: [...s.log, { level: 'info', message: `Imported ${data.type} ${data.source_vmid} to ${data.new_vmid}` }] }));
            })
            .catch((e) => setStatus((s) => ({ ...s, log: [...s.log, { level: 'error', message: e.message }] })))
            .finally(() => setLoading(false));
    };

    return (
        <div className="mt-4 p-3 border rounded border-proxmox-border/50 bg-proxmox-dark">
            <div className="font-medium text-[13px] mb-2" style={{ color: '#e9ecef' }}>{t('packerImport')}</div>
            <select className="w-full mb-2 px-2 py-1 text-[12px] rounded bg-proxmox-hover text-proxmox-text border border-proxmox-border" value={selected} onChange={(e) => setSelected(e.target.value)} disabled={loading}>
                <option value="">{t('selectTemplate')}</option>
                {templates.map((tmpl) => (
                    <option key={tmpl.vmid} value={tmpl.vmid}>{tmpl.name} ({tmpl.vmid})</option>
                ))}
            </select>
            <div className="flex gap-2">
                <button className="px-3 py-1 text-[12px] rounded bg-proxmox-primary text-white" onClick={doImport} disabled={!selected || loading}>{t('importNow')}</button>
            </div>
            <PackerImportStatus imported={imported.imported} newVmid={imported.newVmid} />
        </div>
    );
}

