function PackerRoleMapping({ clusterId }) {
    const { t } = useTranslation();
    const [roles, setRoles] = React.useState([]);
    const [newRoleName, setNewRoleName] = React.useState('');
    const [newRolePerms, setNewRolePerms] = React.useState('packer.view');
    const [loading, setLoading] = React.useState(false);

    const loadRoles = () => {
        setLoading(true);
        fetch(`/api/clusters/${clusterId}/packer/roles`)
            .then((r) => r.json())
            .then((data) => setRoles(data.roles || []))
            .finally(() => setLoading(false));
    };

    const saveRoles = () => {
        setLoading(true);
        fetch(`/api/clusters/${clusterId}/packer/roles`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ roles })
        })
            .then((r) => r.json())
            .then((data) => setRoles(data.roles || []))
            .finally(() => setLoading(false));
    };

    const addRole = () => {
        if (!newRoleName.trim()) return;
        const perms = newRolePerms.split(',').map((s) => s.trim()).filter(Boolean);
        const role = {
            id: newRoleName.toLowerCase().replace(/\s+/g, '-'),
            name: newRoleName.trim(),
            permissions: perms,
        };
        setRoles([...roles, role]);
        setNewRoleName('');
        setNewRolePerms('packer.view');
    };

    const removeRole = (id) => {
        setRoles(roles.filter((r) => r.id !== id));
    };

    return (
        <div className="mt-4 p-3 border rounded border-proxmox-border/50 bg-proxmox-dark">
            <div className="font-medium text-[13px] mb-2" style={{ color: '#e9ecef' }}>{t('packerRoleMapping')}</div>
            <div className="space-y-1 mb-2 max-h-32 overflow-auto">
                {roles.map((role) => (
                    <div key={role.id} className="flex justify-between items-center text-[12px] p-1 rounded bg-proxmox-hover" style={{ color: 'var(--corp-text-secondary)' }}>
                        <span>{role.name} — {role.permissions.join(', ')}</span>
                        <button className="text-[10px] text-proxmox-danger" onClick={() => removeRole(role.id)} disabled={loading}>{t('remove')}</button>
                    </div>
                ))}
            </div>
            <div className="flex gap-2 mb-2">
                <input
                    type="text"
                    className="flex-1 px-2 py-1 text-[12px] rounded bg-proxmox-hover text-proxmox-text border border-proxmox-border"
                    value={newRoleName}
                    onChange={(e) => setNewRoleName(e.target.value)}
                    placeholder={t('roleName')}
                    disabled={loading}
                />
                <input
                    type="text"
                    className="flex-1 px-2 py-1 text-[12px] rounded bg-proxmox-hover text-proxmox-text border border-proxmox-border"
                    value={newRolePerms}
                    onChange={(e) => setNewRolePerms(e.target.value)}
                    placeholder={t('permissions')}
                    disabled={loading}
                />
            </div>
            <div className="flex gap-2">
                <button className="px-3 py-1 text-[12px] rounded bg-proxmox-primary text-white" onClick={addRole} disabled={loading}>{t('addRole')}</button>
                <button className="px-3 py-1 text-[12px] rounded bg-proxmox-primary text-white" onClick={saveRoles} disabled={loading}>{t('save')}</button>
                <button className="px-3 py-1 text-[12px] rounded bg-proxmox-hover text-white" onClick={loadRoles} disabled={loading}>{t('reload')}</button>
            </div>
        </div>
    );
}

