function KubernetesPolicyAdapter({ clusterId }) {
    const { t } = useTranslation();
    const [config, setConfig] = React.useState({ enabled: false, engine: 'kyverno', policies: [] });
    const [newPolicy, setNewPolicy] = React.useState('');
    const [loading, setLoading] = React.useState(false);

    const loadPolicy = () => {
        setLoading(true);
        fetch(`/api/clusters/${clusterId}/kubernetes/policy`)
            .then((r) => r.json())
            .then((data) => setConfig(data.policy || config))
            .finally(() => setLoading(false));
    };

    const savePolicy = () => {
        setLoading(true);
        fetch(`/api/clusters/${clusterId}/kubernetes/policy`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ policy: config })
        })
            .then((r) => r.json())
            .then((data) => {
                if (data.success) {
                    setConfig(data.policy);
                }
            })
            .finally(() => setLoading(false));
    };

    const addPolicy = () => {
        if (!newPolicy.trim()) return;
        setConfig({ ...config, policies: [...(config.policies || []), newPolicy.trim()] });
        setNewPolicy('');
    };

    const removePolicy = (idx) => {
        setConfig({ ...config, policies: (config.policies || []).filter((_, i) => i !== idx) });
    };

    React.useEffect(loadPolicy, [clusterId]);

    return (
        <div className="mt-4 p-3 border rounded border-proxmox-border/50 bg-proxmox-dark">
            <div className="font-medium text-[13px] mb-2" style={{ color: '#e9ecef' }}>{t('kubernetesPolicyAdapter')}</div>
            {loading && <div className="text-[12px]" style={{ color: 'var(--corp-text-secondary)' }}>{t('loading')}</div>}
            <label className="flex items-center gap-2 text-[12px] mb-2" style={{ color: 'var(--corp-text-secondary)' }}>
                <input
                    type="checkbox"
                    checked={config.enabled}
                    onChange={(e) => setConfig({ ...config, enabled: e.target.checked })}
                    disabled={loading}
                    className="accent-proxmox-primary"
                />
                {t('enabled')}
            </label>
            <label className="block text-[12px] mb-1" style={{ color: 'var(--corp-text-secondary)' }}>{t('engine')}</label>
            <select
                className="w-full mb-2 px-2 py-1 text-[12px] rounded bg-proxmox-hover text-proxmox-text border border-proxmox-border"
                value={config.engine}
                onChange={(e) => setConfig({ ...config, engine: e.target.value })}
                disabled={loading}
            >
                <option value="kyverno">Kyverno</option>
                <option value="opa">OPA</option>
                <option value="none">{t('none')}</option>
            </select>
            <div className="space-y-1 mb-2">
                {(config.policies || []).map((p, idx) => (
                    <div key={idx} className="flex items-center justify-between p-1 rounded bg-proxmox-hover border border-proxmox-border">
                        <span className="text-[12px]" style={{ color: '#e9ecef' }}>{p}</span>
                        <button className="text-[11px] text-red-400" onClick={() => removePolicy(idx)} disabled={loading}>{t('remove')}</button>
                    </div>
                ))}
            </div>
            <div className="flex gap-2 mb-2">
                <input
                    type="text"
                    className="flex-1 px-2 py-1 text-[12px] rounded bg-proxmox-hover text-proxmox-text border border-proxmox-border"
                    value={newPolicy}
                    onChange={(e) => setNewPolicy(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && addPolicy()}
                    placeholder={t('newPolicy')}
                    disabled={loading}
                />
                <button className="px-3 py-1 text-[12px] rounded bg-proxmox-primary text-white" onClick={addPolicy} disabled={loading}>{t('add')}</button>
            </div>
            <button className="px-3 py-1 text-[12px] rounded bg-proxmox-primary text-white" onClick={savePolicy} disabled={loading}>{t('save')}</button>
        </div>
    );
}

