// BackupCalendarKeyboardShortcuts: global keyboard shortcuts for the Backup Calendar page.
function BackupCalendarKeyboardShortcuts({ shortcuts, onShortcut }) {
    useEffect(() => {
        const handler = (e) => {
            const combo = [
                e.ctrlKey ? 'ctrl' : '',
                e.shiftKey ? 'shift' : '',
                e.altKey ? 'alt' : '',
                e.key?.toLowerCase()
            ].filter(Boolean).join('+');
            if (shortcuts?.includes(combo) && onShortcut) {
                e.preventDefault();
                onShortcut(combo);
            }
        };
        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [shortcuts, onShortcut]);

    return null;
}

// SnapshotRestoreBulkSelection: bulk select snapshots for restore.
function SnapshotRestoreBulkSelection({ items = [], onSelect }) {
    const [selected, setSelected] = React.useState({});
    const toggle = (id) => {
        const next = { ...selected, [id]: !selected[id] };
        setSelected(next);
        if (onSelect) onSelect(Object.keys(next).filter(k => next[k]));
    };
    const selectAll = () => {
        const all = {};
        items.forEach((item) => { all[item.id] = true; });
        setSelected(all);
        if (onSelect) onSelect(items.map(i => i.id));
    };
    const clearAll = () => {
        setSelected({});
        if (onSelect) onSelect([]);
    };
    return (
        <div className="p-3 rounded border border-proxmox-border bg-proxmox-card" data-testid="snapshot-restore-bulk-selection">
            <div className="text-sm font-medium mb-2" style={{ color: 'var(--corp-text)' }}>Bulk select snapshots</div>
            <div className="flex gap-2 mb-2">
                <button onClick={selectAll} className="px-2 py-1 text-xs rounded bg-cyan-600 hover:bg-cyan-700">Select all</button>
                <button onClick={clearAll} className="px-2 py-1 text-xs rounded bg-proxmox-dark hover:bg-proxmox-hover">Clear</button>
            </div>
            <div className="space-y-1 max-h-40 overflow-y-auto">
                {items.map((item) => (
                    <label key={item.id} className="flex items-center gap-2 text-sm" style={{ color: 'var(--corp-text-secondary)' }}>
                        <input
                            type="checkbox"
                            checked={!!selected[item.id]}
                            onChange={() => toggle(item.id)}
                        />
                        {item.label}
                    </label>
                ))}
            </div>
        </div>
    );
}

// SnapshotRestoreStepWizard: step-by-step wizard for snapshot restore.
