// 928-filter-sidebar-for-backup-jobs: predicate for Backup Jobs sidebar filters.
function matchesBackupJobFilter(job, filters) {
    if (!filters) return true;
    const keyword = (filters.keyword || '').toLowerCase();
    if (keyword) {
        const haystack = [job.id, job.store, job.remote, job.schedule].filter(Boolean).join(' ').toLowerCase();
        if (!haystack.includes(keyword)) return false;
    }
    if (filters.store !== 'all' && job.store !== filters.store) return false;
    const status = (job.status || (job['last-run-endtime'] ? 'success' : 'idle')).toLowerCase();
    if (filters.status !== 'all' && status !== filters.status) return false;
    return true;
}

