// BackupJobsResizablePanels: resizable left/right panels for the Backup Jobs page.
// 922-resizable-panels-for-backup-jobs: lets operators resize the jobs list and detail panels.
function BackupJobsResizablePanels({ left, right, initialLeftPercent = 60 }) {
    const [leftPercent, setLeftPercent] = React.useState(initialLeftPercent);
    const [dragging, setDragging] = React.useState(false);
    const containerRef = React.useRef(null);

    React.useEffect(() => {
        if (!dragging) return;
        const handleMove = (e) => {
            if (!containerRef.current) return;
            const rect = containerRef.current.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const percent = Math.min(Math.max((x / rect.width) * 100, 20), 80);
            setLeftPercent(percent);
        };
        const handleUp = () => setDragging(false);
        window.addEventListener('mousemove', handleMove);
        window.addEventListener('mouseup', handleUp);
        return () => {
            window.removeEventListener('mousemove', handleMove);
            window.removeEventListener('mouseup', handleUp);
        };
    }, [dragging]);

    return (
        <div ref={containerRef} className="flex w-full min-h-96" data-testid="backup-jobs-resizable-panels">
            <div className="overflow-auto" style={{ width: `${leftPercent}%` }}>
                {left}
            </div>
            <div
                className="w-1 shrink-0 cursor-col-resize bg-gray-500 hover:bg-gray-400 transition-colors"
                onMouseDown={() => setDragging(true)}
                data-testid="backup-jobs-resize-handle"
            />
            <div className="overflow-auto" style={{ width: `${100 - leftPercent}%` }}>
                {right}
            </div>
        </div>
    );
}

